$ErrorActionPreference = "Stop"
Set-StrictMode -Version 2

function Section {
    param([string]$Title)
    Write-Host ""
    Write-Host "=== $Title ===" -ForegroundColor Cyan
}

function Run-Checked {
    param(
        [Parameter(Mandatory=$true)][string]$Command,
        [Parameter(Mandatory=$true)][string[]]$CommandArguments
    )

    Write-Host "> $Command $($CommandArguments -join ' ')" -ForegroundColor DarkGray
    & $Command @CommandArguments

    if ($LASTEXITCODE -ne 0) {
        throw "$Command failed with exit code $LASTEXITCODE"
    }
}

function Decode-Text {
    param([Parameter(Mandatory=$true)][string]$Base64)
    $bytes = [Convert]::FromBase64String($Base64)
    return [Text.Encoding]::UTF8.GetString($bytes)
}

function Full-Path {
    param([Parameter(Mandatory=$true)][string]$RelativePath)
    return [IO.Path]::GetFullPath(
        [IO.Path]::Combine(
            (Get-Location).Path,
            $RelativePath.Replace("/", [IO.Path]::DirectorySeparatorChar)
        )
    )
}

function Read-LiteralText {
    param([Parameter(Mandatory=$true)][string]$RelativePath)
    $path = Full-Path $RelativePath
    if (![IO.File]::Exists($path)) {
        throw "Required file missing: $RelativePath"
    }
    return [IO.File]::ReadAllText($path).Replace("`r`n", "`n")
}

function Write-LiteralText {
    param(
        [Parameter(Mandatory=$true)][string]$RelativePath,
        [Parameter(Mandatory=$true)][string]$Content
    )
    $path = Full-Path $RelativePath
    $dir = [IO.Path]::GetDirectoryName($path)
    if (![IO.Directory]::Exists($dir)) {
        [IO.Directory]::CreateDirectory($dir) | Out-Null
    }
    $utf8 = New-Object Text.UTF8Encoding($false)
    [IO.File]::WriteAllText(
        $path,
        $Content.Replace("`r`n", "`n").TrimEnd() + "`n",
        $utf8
    )
}

function Replace-Once {
    param(
        [Parameter(Mandatory=$true)][string]$Text,
        [Parameter(Mandatory=$true)][string]$Old,
        [Parameter(Mandatory=$true)][string]$New,
        [Parameter(Mandatory=$true)][string]$Label
    )

    $first = $Text.IndexOf($Old, [StringComparison]::Ordinal)
    if ($first -lt 0) {
        throw "Patch anchor not found: $Label"
    }

    $second = $Text.IndexOf(
        $Old,
        $first + $Old.Length,
        [StringComparison]::Ordinal
    )
    if ($second -ge 0) {
        throw "Patch anchor is ambiguous: $Label"
    }

    return $Text.Substring(0, $first) +
        $New +
        $Text.Substring($first + $Old.Length)
}

function Backup-TrackedFile {
    param(
        [Parameter(Mandatory=$true)][string]$RelativePath,
        [Parameter(Mandatory=$true)][string]$BackupRoot
    )
    $source = Full-Path $RelativePath
    $dest = Join-Path $BackupRoot $RelativePath.Replace("/", "\")
    $destDir = [IO.Path]::GetDirectoryName($dest)
    if (![IO.Directory]::Exists($destDir)) {
        [IO.Directory]::CreateDirectory($destDir) | Out-Null
    }
    [IO.File]::Copy($source, $dest, $true)
}

function Restore-TrackedFile {
    param(
        [Parameter(Mandatory=$true)][string]$RelativePath,
        [Parameter(Mandatory=$true)][string]$BackupRoot
    )
    $backup = Join-Path $BackupRoot $RelativePath.Replace("/", "\")
    $dest = Full-Path $RelativePath
    if ([IO.File]::Exists($backup)) {
        [IO.File]::Copy($backup, $dest, $true)
    }
}

Section "Repository safety"

if (!(Test-Path -LiteralPath ".git")) {
    throw "Run this script from the repository root."
}

if ((git branch --show-current).Trim() -ne "main") {
    throw "Expected main branch."
}

Run-Checked "git" @("fetch", "origin")

$local = (git rev-parse HEAD).Trim()
$remote = (git rev-parse origin/main).Trim()

Write-Host "Local:  $($local.Substring(0,7))"
Write-Host "Remote: $($remote.Substring(0,7))"

if ($local -ne $remote) {
    throw "origin/main moved. Reconcile before applying this batch."
}

Section "Clean generated Prisma line-ending noise"

& git diff --quiet --ignore-space-at-eol -- generated/prisma
if ($LASTEXITCODE -eq 0) {
    Run-Checked "git" @(
        "restore",
        "--worktree",
        "--source=HEAD",
        "--",
        "generated/prisma"
    )
    Write-Host "Generated Prisma noise removed."
}
else {
    throw "generated/prisma contains a semantic diff. Refusing to restore it."
}

$trackedTargets = @(
    "app/suppliers/page.tsx",
    "app/supplier-prices/page.tsx",
    "tests/club-governance.integration.test.ts"
)

$newTargets = @(
    "lib/supplier-import.ts",
    "lib/supplier-import-controls.ts",
    "lib/supplier-import.test.ts",
    "app/suppliers/import-actions.ts",
    "app/suppliers/import-panel.tsx",
    "app/supplier-prices/import-actions.ts",
    "app/supplier-prices/import-panel.tsx"
)

Section "Preflight target state"

foreach ($file in $trackedTargets) {
    & git diff --quiet -- $file
    if ($LASTEXITCODE -ne 0) {
        throw "Unexpected local change in target file: $file"
    }
    Write-Host "Clean: $file"
}

foreach ($file in $newTargets) {
    if ([IO.File]::Exists((Full-Path $file))) {
        throw "Target new file already exists: $file"
    }
    Write-Host "Available: $file"
}

Section "Preflight exact patch anchors"
$supplierImportOld = Decode-Text "aW1wb3J0IHsgbm90Rm91bmQgfSBmcm9tICJuZXh0L25hdmlnYXRpb24iOw=="
$supplierImportNew = Decode-Text "aW1wb3J0IHsgbm90Rm91bmQgfSBmcm9tICJuZXh0L25hdmlnYXRpb24iOwppbXBvcnQgeyBTdXBwbGllclJvc3RlckltcG9ydFBhbmVsIH0gZnJvbSAiLi9pbXBvcnQtcGFuZWwiOw=="
$supplierPanelOld = Decode-Text "ICAgICAge21heU1hbmFnZSAmJiAoCiAgICAgICAgPENhcmQ+"
$supplierPanelNew = Decode-Text "ICAgICAgPFN1cHBsaWVyUm9zdGVySW1wb3J0UGFuZWwKICAgICAgICBhY3RvcklkPXt1c2VyLmlkfQogICAgICAgIG1heU1hbmFnZT17bWF5TWFuYWdlfQogICAgICAgIG1heUFwcHJvdmU9e21heUFwcHJvdmV9CiAgICAgIC8+CiAgICAgIHttYXlNYW5hZ2UgJiYgKAogICAgICAgIDxDYXJkPg=="
$priceImportOld = Decode-Text "aW1wb3J0IHsgcHJvcG9zZVN1cHBsaWVyUHJpY2UsIHJlcXVlc3RQcmljZUV4Y2VwdGlvbiB9IGZyb20gIi4vYWN0aW9ucyI7"
$priceImportNew = Decode-Text "aW1wb3J0IHsgcHJvcG9zZVN1cHBsaWVyUHJpY2UsIHJlcXVlc3RQcmljZUV4Y2VwdGlvbiB9IGZyb20gIi4vYWN0aW9ucyI7CmltcG9ydCB7IFN1cHBsaWVyUHJpY2VJbXBvcnRQYW5lbCB9IGZyb20gIi4vaW1wb3J0LXBhbmVsIjs="
$pricePanelOld = Decode-Text "PExpbmsgaHJlZj0iL2FwcHJvdmFscyI+UmV2aWV3IGFwcHJvdmFsIHJlcXVlc3RzPC9MaW5rPjwvaGVhZGVyPgogICAgeyFwcmljZXMubGVuZ3Ro"
$pricePanelNew = Decode-Text ""
$integrationImportOld = Decode-Text "aW1wb3J0IHsgcmVjb3JkU3RvcmVrZWVwZXJSZWNlaXB0QWN0aW9uIH0gZnJvbSAiQC9hcHAvY29udHJvbHMvcmVjZWlwdC1hY3Rpb25zIjs="
$integrationImportNew = Decode-Text ""
$integrationAnchor = Decode-Text "ICBpdCgiYWNjZXB0cyBzZXBhcmF0ZSBwYXJ0aWFsIGRlbGl2ZXJpZXMgYW5kIGJsb2NrcyBkdXBsaWNhdGUgbm90ZXMgYW5kIG92ZXItcmVjZWlwdCIsIGFzeW5jICgpID0+IHs="
$integrationTests = Decode-Text ""

$supplierPage = Read-LiteralText "app/suppliers/page.tsx"
$pricePage = Read-LiteralText "app/supplier-prices/page.tsx"
$integration = Read-LiteralText "tests/club-governance.integration.test.ts"

# These calls only validate anchors in memory. Nothing is written yet.
$null = Replace-Once $supplierPage $supplierImportOld $supplierImportNew "supplier page import"
$null = Replace-Once $supplierPage $supplierPanelOld $supplierPanelNew "supplier roster panel placement"
$null = Replace-Once $pricePage $priceImportOld $priceImportNew "supplier price import"
$null = Replace-Once $pricePage $pricePanelOld $pricePanelNew "supplier price panel placement"
$null = Replace-Once $integration $integrationImportOld $integrationImportNew "integration imports"
$null = Replace-Once $integration $integrationAnchor ($integrationTests + $integrationAnchor) "integration test insertion"

Write-Host "All exact anchors verified before any source write."

$backupRoot = Join-Path $env:TEMP ("nbi-supplier-import-backup-" + [Guid]::NewGuid().ToString("N"))
[IO.Directory]::CreateDirectory($backupRoot) | Out-Null

foreach ($file in $trackedTargets) {
    Backup-TrackedFile $file $backupRoot
}

$completed = $false

try {
    Section "Write supplier import implementation"
    Write-LiteralText "lib/supplier-import.ts" (Decode-Text "")
    Write-LiteralText "lib/supplier-import-controls.ts" (Decode-Text "")
    Write-LiteralText "app/suppliers/import-actions.ts" (Decode-Text "")
    Write-LiteralText "app/supplier-prices/import-actions.ts" (Decode-Text "")
    Write-LiteralText "app/suppliers/import-panel.tsx" (Decode-Text "")
    Write-LiteralText "app/supplier-prices/import-panel.tsx" (Decode-Text "")
    Write-LiteralText "lib/supplier-import.test.ts" (Decode-Text "")

    Section "Patch existing pages"

    $supplierPage = Replace-Once $supplierPage $supplierImportOld $supplierImportNew "supplier page import"
    $supplierPage = Replace-Once $supplierPage $supplierPanelOld $supplierPanelNew "supplier roster panel placement"
    Write-LiteralText "app/suppliers/page.tsx" $supplierPage

    $pricePage = Replace-Once $pricePage $priceImportOld $priceImportNew "supplier price import"
    $pricePage = Replace-Once $pricePage $pricePanelOld $pricePanelNew "supplier price panel placement"
    Write-LiteralText "app/supplier-prices/page.tsx" $pricePage

    Section "Patch DB integration coverage"

    $integration = Replace-Once $integration $integrationImportOld $integrationImportNew "integration imports"
    $integration = Replace-Once $integration $integrationAnchor ($integrationTests + $integrationAnchor) "integration test insertion"
    Write-LiteralText "tests/club-governance.integration.test.ts" $integration

    Section "Static validation"

    $npx = (Get-Command "npx.cmd" -ErrorAction Stop).Source
    $npm = (Get-Command "npm.cmd" -ErrorAction Stop).Source

    Run-Checked $npx @(
        "tsc",
        "--noEmit"
    )

    Run-Checked $npx @(
        "vitest",
        "run",
        "lib/supplier-import.test.ts",
        "lib/financial-integrity.test.ts",
        "lib/email-delivery-outcome.test.ts"
    )

    Run-Checked $npm @(
        "run",
        "lint"
    )

    Section "Production build"

    Run-Checked $npm @(
        "run",
        "build"
    )

    Section "Diff integrity"

    Run-Checked "git" @(
        "diff",
        "--check"
    )

    $completed = $true
}
finally {
    if (!$completed) {
        Section "Automatic rollback of this supplier-import batch"

        foreach ($file in $trackedTargets) {
            Restore-TrackedFile $file $backupRoot
        }

        foreach ($file in $newTargets) {
            $path = Full-Path $file
            if ([IO.File]::Exists($path)) {
                [IO.File]::Delete($path)
            }
        }

        Write-Host "Supplier-import batch changes were rolled back."
        Write-Host "Your previously validated work was preserved."
    }

    if ([IO.Directory]::Exists($backupRoot)) {
        Remove-Item -LiteralPath $backupRoot -Recurse -Force
    }
}

Section "Result"

git status --short

Write-Host ""
git diff --stat

Write-Host ""
Write-Host "=== SUPPLIER IMPORT STATIC VALIDATION PASSED ===" -ForegroundColor Green
Write-Host "Supplier roster staging/preview/duplicate controls: added"
Write-Host "Supplier price-list staging/overlap controls: added"
Write-Host "Procurement maker / CFO checker: enforced"
Write-Host "Real data loaded: none"
Write-Host "New migration: none required"
Write-Host "Commit/push/deploy: not performed"
Write-Host ""
Write-Host "Next run the proven disposable-PostgreSQL validator:"
Write-Host "  .\validate-financial-repair-v5.ps1"
